    프레임 += 1

    while state['queue']:
        종류, 값 = state['queue'].pop(0)
        if 종류 == 'click':
            for i, 건반 in enumerate(건반들):
                if 건반._id == 값:
                    음재생(i)
                    break
        elif 종류 == 'key':
            키 = 값
