from vpython import *
class Planet:
    def __init__(self, r, c):
        self.ball = sphere(radius=r, color=c, make_trail=True)
        self.angle = 0
    def move(self, dt):
        self.angle += dt
        self.ball.pos = vector(cos(self.angle), 0, sin(self.angle))
p = Planet(0.3, color.blue)
for i in range(10):
    rate(100)
    p.move(0.1)
